svg.script:

(function () {
  var root = document.getElementById('a16p9-svg');
  if (!root) {
    var all = document.getElementsByClassName('a16p9-root');
    root = all && all[0] ? all[0] : null;
  }
  if (!root) return;

  var cases = {
    none: {
      verdict: 'none',
      main: 'Escolha um caso',
      sub: 'A árvore inteira já ensina sem clique',
      sub2: 'Antibiótico = intraparto',
      nodes: [],
      edges: []
    },
    abs: {
      verdict: 'iap',
      main: 'IAP SIM · no parto',
      sub: 'Indicação absoluta · não rastrear',
      sub2: 'ATB só no parto · não no PN',
      nodes: ['a16p9-n-start', 'a16p9-n-abs', 'a16p9-n-iap'],
      edges: ['a16p9-e-start-abs', 'a16p9-e-abs-iap']
    },
    swabpos: {
      verdict: 'iap',
      main: 'IAP SIM · no parto',
      sub: 'Swab + = info p/ maternidade',
      sub2: 'Zero penicilina no consultório',
      nodes: ['a16p9-n-start', 'a16p9-n-abs', 'a16p9-n-swab', 'a16p9-n-pos', 'a16p9-n-iap'],
      edges: ['a16p9-e-start-abs', 'a16p9-e-abs-swab', 'a16p9-e-swab-pos', 'a16p9-e-pos-iap']
    },
    swabneg: {
      verdict: 'no',
      main: 'SEM IAP por GBS',
      sub: 'Negativo válido <5 semanas',
      sub2: 'Sem tríade de risco',
      nodes: ['a16p9-n-start', 'a16p9-n-abs', 'a16p9-n-swab', 'a16p9-n-neg', 'a16p9-n-no'],
      edges: ['a16p9-e-start-abs', 'a16p9-e-abs-swab', 'a16p9-e-swab-neg', 'a16p9-e-neg-no']
    },
    expired: {
      verdict: 'iap',
      main: 'IAP SIM · no parto',
      sub: '− expirado = desconhecido',
      sub2: 'BR >18 h aciona IAP',
      nodes: ['a16p9-n-start', 'a16p9-n-abs', 'a16p9-n-swab', 'a16p9-n-neg', 'a16p9-n-unk', 'a16p9-n-risk', 'a16p9-n-iap'],
      edges: ['a16p9-e-start-abs', 'a16p9-e-abs-swab', 'a16p9-e-swab-neg', 'a16p9-e-neg-unk', 'a16p9-e-unk-risk', 'a16p9-e-risk-iap']
    },
    risk: {
      verdict: 'iap',
      main: 'IAP SIM · no parto',
      sub: 'Desconhecido + TPP',
      sub2: 'Idem febre IP e BR >18 h',
      nodes: ['a16p9-n-start', 'a16p9-n-abs', 'a16p9-n-swab', 'a16p9-n-unk', 'a16p9-n-risk', 'a16p9-n-iap'],
      edges: ['a16p9-e-start-abs', 'a16p9-e-abs-swab', 'a16p9-e-swab-unk', 'a16p9-e-unk-risk', 'a16p9-e-risk-iap']
    },
    cs: {
      verdict: 'no',
      main: 'SEM IAP por GBS',
      sub: 'Cesárea eletiva: sem TP + bolsa íntegra',
      sub2: 'Mesmo se swab + ou indicação absoluta',
      nodes: ['a16p9-n-start', 'a16p9-n-cs', 'a16p9-n-no'],
      edges: ['a16p9-e-start-cs', 'a16p9-e-cs-no']
    },
    norisk: {
      verdict: 'no',
      main: 'SEM IAP por GBS',
      sub: 'Desconhecida sem TPP / febre / BR',
      sub2: 'Sem fator de risco → sem IAP',
      nodes: ['a16p9-n-start', 'a16p9-n-abs', 'a16p9-n-swab', 'a16p9-n-unk', 'a16p9-n-risk', 'a16p9-n-no'],
      edges: ['a16p9-e-start-abs', 'a16p9-e-abs-swab', 'a16p9-e-swab-unk', 'a16p9-e-unk-risk', 'a16p9-e-risk-no']
    }
  };

  var btnIds = [
    'a16p9-btn-abs', 'a16p9-btn-swabpos', 'a16p9-btn-swabneg', 'a16p9-btn-expired',
    'a16p9-btn-risk', 'a16p9-btn-cs', 'a16p9-btn-norisk', 'a16p9-btn-reset'
  ];
  var vKicker = document.getElementById('a16p9-verdict-kicker');
  var vMain = document.getElementById('a16p9-verdict-main');
  var vSub = document.getElementById('a16p9-verdict-sub');
  var vSub2 = document.getElementById('a16p9-verdict-sub2');
  var tooltip = document.getElementById('a16p9-tooltip');
  var tipBg = document.getElementById('a16p9-tooltip-bg');
  var tipTitle = document.getElementById('a16p9-tooltip-title');
  var tipBody = document.getElementById('a16p9-tooltip-body');

  function clearOn() {
    var on = root.querySelectorAll('.a16p9-on');
    for (var i = 0; i < on.length; i++) on[i].classList.remove('a16p9-on');
    for (var j = 0; j < btnIds.length; j++) {
      var b = document.getElementById(btnIds[j]);
      if (b) b.classList.remove('a16p9-active');
    }
  }

  function setCase(key) {
    var cfg = cases[key] || cases.none;
    clearOn();
    root.setAttribute('data-case', key);
    root.setAttribute('data-verdict', cfg.verdict);
    if (vKicker) {
      vKicker.textContent = cfg.verdict === 'iap' ? 'IAP NO PARTO' : (cfg.verdict === 'no' ? 'SEM IAP-GBS' : 'VEREDITO');
    }
    if (vMain) vMain.textContent = cfg.main;
    if (vSub) vSub.textContent = cfg.sub;
    if (vSub2) vSub2.textContent = cfg.sub2 || '';
    var n;
    for (n = 0; n < cfg.nodes.length; n++) {
      var node = document.getElementById(cfg.nodes[n]);
      if (node) node.classList.add('a16p9-on');
    }
    for (n = 0; n < cfg.edges.length; n++) {
      var edge = document.getElementById(cfg.edges[n]);
      if (edge) edge.classList.add('a16p9-on');
    }
    if (key !== 'none') {
      for (var k = 0; k < btnIds.length; k++) {
        var btn = document.getElementById(btnIds[k]);
        if (btn && btn.getAttribute('data-case') === key) btn.classList.add('a16p9-active');
      }
    }
  }

  function bindBtn(id) {
    var el = document.getElementById(id);
    if (!el) return;
    var run = function () {
      setCase(el.getAttribute('data-case') || 'none');
    };
    el.addEventListener('click', run);
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        run();
      }
    });
  }
  for (var i = 0; i < btnIds.length; i++) bindBtn(btnIds[i]);

  function showTip(title, body, clientX, clientY) {
    if (!tooltip || !tipTitle || !tipBody) return;
    tipTitle.textContent = title || '';
    tipBody.textContent = body || '';
    var tw = 280;
    var lines = Math.ceil((body || '').length / 42);
    var th = 40 + Math.max(1, Math.min(lines, 3)) * 14;
    if (tipBg) {
      tipBg.setAttribute('width', String(tw));
      tipBg.setAttribute('height', String(th));
    }
    tooltip.classList.add('a16p9-show');
    moveTip(clientX, clientY);
  }

  function moveTip(clientX, clientY) {
    if (!tooltip || !tooltip.classList.contains('a16p9-show')) return;
    var ctm = root.getScreenCTM();
    if (!ctm) return;
    var pt = root.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    var sp = pt.matrixTransform(ctm.inverse());
    var x = sp.x + 14;
    var y = sp.y + 14;
    var vb = root.viewBox.baseVal;
    var maxX = (vb && vb.width ? vb.width : 1000) - 292;
    var maxY = (vb && vb.height ? vb.height : 780) - 70;
    if (x > maxX) x = sp.x - 294;
    if (y > maxY) y = sp.y - 70;
    if (x < 8) x = 8;
    if (y < 8) y = 8;
    tooltip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
  }

  function hideTip() {
    if (tooltip) tooltip.classList.remove('a16p9-show');
  }

  var tips = root.querySelectorAll('[data-tip-title]');
  for (var t = 0; t < tips.length; t++) {
    (function (el) {
      el.addEventListener('mouseenter', function (e) {
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), e.clientX, e.clientY);
      });
      el.addEventListener('mousemove', function (e) {
        moveTip(e.clientX, e.clientY);
      });
      el.addEventListener('mouseleave', hideTip);
      el.addEventListener('focus', function () {
        var r = el.getBoundingClientRect();
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), r.left + r.width / 2, r.top);
      });
      el.addEventListener('blur', hideTip);
    })(tips[t]);
  }

  root.addEventListener('mousemove', function (e) {
    moveTip(e.clientX, e.clientY);
  });

  setCase('none');
})();
